import React, { useEffect, useState } from 'react';
import axios            from 'axios';
import { useParams, useNavigate } from 'react-router-dom';

export default function EditDeliveryForm() {
  const { id } = useParams<{id:string}>();
  const [f, setF] = useState({ customerId:'', address:'', status:'Pending' });
  const nav = useNavigate();

  useEffect(()=>{
    axios.get(`${process.env.REACT_APP_API_URL}/api/delivery/${id}`)
         .then(r=>setF(r.data));
  },[id]);

  const sub = async (e:any) => {
    e.preventDefault();
    await axios.put(`${process.env.REACT_APP_API_URL}/api/delivery/${id}`, f);
    nav('/');
  };

  return (
    <form onSubmit={sub} style={{padding:20,maxWidth:400,margin:'auto'}}>
      <h3>Edit Delivery</h3>
      <input value={f.customerId}
             onChange={e=>setF({...f,customerId:e.target.value})}/>
      <input value={f.address}
             onChange={e=>setF({...f,address:e.target.value})}/>
      <select value={f.status} onChange={e=>setF({...f,status:e.target.value})}>
        {['Pending','Assigned','In Transit','Delivered'].map(s=>
          <option key={s} value={s}>{s}</option>)}
      </select>
      <button type="submit">Save</button>
    </form>
  );
}
